1551	    Unit = {
1552	      Description = "Gracefully close all Hyprland windows on session end";
1553	      PartOf = [ "graphical-session.target" ];
1554	      After = [ "graphical-session.target" ];
1555	      # The ExecStop below closes every Hyprland window and fires whenever this
1556	      # unit stops for *any* reason. When a home-manager switch changes a store
1557	      # path in this unit, sd-switch would otherwise restart it and run ExecStop
1558	      # mid-switch, closing all windows (see the 2026-07 firefox incident).
1559	      # keep-old tells sd-switch to leave the running unit untouched during a
1560	      # switch. Real logout still stops graphical-session.target, which stops
1561	      # this unit via PartOf and runs ExecStop as intended.
1562	      X-SwitchMethod = "keep-old";
1563	    };
1564	    Service = {
1565	      Type = "oneshot";
1566	      RemainAfterExit = true;
1567	      ExecStart = "${pkgs.coreutils}/bin/true";
1568	      ExecStop = "${config.home.homeDirectory}/.local/bin/hyprland-graceful-exit --no-exit";
1569	    };
