# Samples opencode's resident memory every 5 minutes and appends one line per
# sample. Purely observational: it reads /proc via ps and writes a log, and it
# never signals a process. opencode leaks (upstream #16697 -- 14 leak classes,
# every comprehensive PR still open as of 1.18.25), so the point is a record of
# how fast it climbs on this box, to decide when a session is worth restarting
# by hand. Restarting one is a human call: these are live agent sessions, and
# picking victims by name is exactly the pattern that kills the wrong pid.
#
# RSS overcounts shared pages, so total_kb is an upper bound across processes,
# not a sum of private memory. Fine for a growth curve; do not read it as
# "opencode is using this much".
systemd.user.services.opencode-memwatch = lib.mkIf (!isDarwin) {
  Unit.Description = "Record opencode resident memory (observational; never signals)";
  Service = {
    Type = "oneshot";
    ExecStart = pkgs.writeShellScript "opencode-memwatch" ''
      set -eu
      PATH=${pkgs.coreutils}/bin:${pkgs.procps}/bin:${pkgs.gawk}/bin
      STATE="$HOME/.local/state/opencode-memwatch"
      LOG="$STATE/rss.log"
      mkdir -p "$STATE"
      # `comm` is truncated to 15 chars by the kernel, so the wrapper shows up
      # as `.opencode-wrapp`; match the full argv instead. Excluding memwatch
      # keeps this sampler's own pipeline out of its sample.
      ps -eo pid=,rss=,args= | awk -v ts="$(date -Is)" '
        $3 ~ /opencode/ && $0 !~ /memwatch/ {
          n++; total += $2;
          if ($2 > max) max = $2;
          procs = procs sprintf(" %s:%s", $1, $2);
        }
        END { printf "%s\tprocs=%d\ttotal_kb=%d\tmax_kb=%d\tpids=%s\n", \
                     ts, n+0, total+0, max+0, procs }
      ' >> "$LOG"
      # A leak watcher that grows without bound is its own joke. Keep the most
      # recent 10k samples (~5 weeks at one per 5 minutes).
      if [ "$(wc -l < "$LOG")" -gt 10000 ]; then
        tail -n 10000 "$LOG" > "$LOG.tmp" && mv "$LOG.tmp" "$LOG"
      fi
    '';
  };
};

systemd.user.timers.opencode-memwatch = lib.mkIf (!isDarwin) {
  Unit.Description = "Sample opencode resident memory every 5 minutes";
  Timer = {
    OnBootSec = "5min";
    OnUnitActiveSec = "5min";
    # The curve matters, not the instant, so let systemd batch this with other
    # wakeups rather than holding a timer slot of its own.
    AccuracySec = "1min";
  };
  Install.WantedBy = [ "timers.target" ];
};

