      if ${pkgs.gnugrep}/bin/grep -q '\["session_id"\]\|\["message_id"\]' "$f"; then
        ${pkgs.gnused}/bin/sed -i \
          -e '/output\.headers\["session_id"\] *= *ctx\.sessionID/d' \
          -e '/output\.headers\["message_id"\] *= *ctx\.messageID/d' \
          "$f"
