      JQ_ARGS+=(--rawfile zaiKey "$ZAI_KEY_FILE")
      JQ_FILTER="$JQ_FILTER | .provider.\"zai-coding-plan\".options.apiKey = (\$zaiKey | sub(\"\\n$\"; \"\"))"
    fi
